// ---------- src/checks.mjs ----------
// Runs inside the page. Same rules the Viewport Wall extension flags live, plus two an agent usually asks for
// (tap targets and text size). Returns plain data: every finding names the element that caused it.
const CHECKS = `(opts => {
  const de = document.documentElement, issues = [];
  // A page with no viewport meta gets a wide layout viewport (980px by default) that Chrome scales down, so
  // innerWidth is not what "fits on screen" means. The initial containing block is.
  const vw = de.clientWidth || innerWidth, vh = de.clientHeight || innerHeight;
  const label = el => {
    if (!el || !el.tagName) return '?';
    const id = el.id ? '#' + el.id : '';
    const cls = (typeof el.className === 'string' && el.className.trim()) ? '.' + el.className.trim().split(/\\s+/).slice(0, 2).join('.') : '';
    const txt = (el.innerText || el.getAttribute?.('alt') || '').trim().replace(/\\s+/g, ' ').slice(0, 40);
    return el.tagName.toLowerCase() + id + cls + (txt ? ' "' + txt + '"' : '');
  };
  const box = el => { const r = el.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
  const add = (kind, message, el, extra) => issues.push({ kind, message, element: el ? label(el) : undefined, rect: el ? box(el) : undefined, ...extra });
  const visible = el => { const r = el.getBoundingClientRect(); if (!r.width || !r.height) return false; const cs = getComputedStyle(el); return cs.visibility !== 'hidden' && cs.display !== 'none' && +cs.opacity > 0.05; };
  // Content wider than its box is only a bug when nobody can reach it. A carousel, a code block or a wide table
  // inside a container that scrolls sideways on purpose is not breakage, so anything inside one is skipped.
  const inScroller = el => {
    for (let p = el.parentElement; p && p !== de; p = p.parentElement) {
      const o = getComputedStyle(p).overflowX;
      if (o !== 'visible') return true;   // an ancestor scrolls it or clips it on purpose; nothing leaks onto the page
    }
    return false;
  };
  const srOnly = el => { const r = el.getBoundingClientRect(); return r.width <= 1 || r.height <= 1; };

  if (!document.querySelector('meta[name="viewport"]')) add('viewport-meta', 'No <meta name="viewport"> tag: mobile browsers will render at a desktop width and scale down.');

  if (de.scrollWidth > de.clientWidth + 1)
    add('overflow', 'Horizontal overflow: the page is ' + de.scrollWidth + 'px wide in a ' + de.clientWidth + 'px viewport, so it scrolls sideways.', null, { pageWidth: de.scrollWidth, viewportWidth: de.clientWidth });

  const all = [...document.body.querySelectorAll('*')].slice(0, opts.maxElements);
  let clipped = 0, fixed = 0, wide = 0, tap = 0, small = 0;
  const culprits = [];
  for (const el of all) {
    if (!visible(el)) continue;
    const r = el.getBoundingClientRect(), cs = getComputedStyle(el);
    // element sticking out of the viewport: the usual cause of the page-level overflow above
    const pinned = cs.position === 'fixed' || cs.position === 'sticky';
    // A normal element sticking out only matters when the page itself scrolls sideways because of it.
    const pageOverflows = de.scrollWidth > vw + 1;
    if (r.width > 0 && (r.right > vw + 1 || r.left < -1) && (pinned || (pageOverflows && r.width <= de.scrollWidth)) && !inScroller(el)) {
      // A pinned element cannot be scrolled into view, so its overflow is always a bug; a normal one is only
      // reported when it is not just a wrapper as wide as the whole document.
      if (pinned) { if (fixed++ < opts.perKind) add('fixed-overflow', 'Fixed or sticky element is ' + Math.round(r.width) + 'px wide in a ' + vw + 'px viewport, so part of it can never be seen.', el); }
      else if (wide++ < opts.perKind) { add('element-overflow', 'Element extends ' + Math.round(Math.max(r.right - vw, -r.left)) + 'px past the viewport edge.', el); culprits.push(el); }
    }
    // text cut off by its own box
    // hidden/clip cuts the text off for good; auto/scroll means the user can still reach it
    const cuts = cs.overflowX === 'hidden' || cs.overflowX === 'clip' || cs.textOverflow === 'ellipsis';
    if (el.scrollWidth > el.clientWidth + 2 && cuts && !srOnly(el) && el.children.length === 0 && (el.innerText || '').trim()) {
      if (clipped++ < opts.perKind) add('clipped-text', 'Text is clipped: ' + el.scrollWidth + 'px of content in a ' + el.clientWidth + 'px box.', el);
    }
    if (opts.touch) {
      // tap targets: WCAG 2.5.8 asks for 24px, platform guidance for 44px
      const tappable = el.matches('a[href],button,[role="button"],input:not([type="hidden"]),select,textarea,summary,label[for]') && !srOnly(el);
      if (tappable && !el.querySelector('a,button,input,select,textarea') && r.width && r.height && (r.width < opts.tapMin || r.height < opts.tapMin) && r.top < vh * 3) {
        if (tap++ < opts.perKind) add('tap-target', 'Tap target is ' + Math.round(r.width) + '×' + Math.round(r.height) + 'px, under the ' + opts.tapMin + 'px minimum.', el);
      }
      const fs = parseFloat(cs.fontSize);
      if (fs && fs < opts.minFont && (el.innerText || '').trim().length > 12 && el.children.length === 0) {
        if (small++ < opts.perKind) add('small-text', 'Text is ' + fs.toFixed(1) + 'px, under the ' + opts.minFont + 'px minimum for comfortable reading on a phone.', el);
      }
    }
  }
  for (const img of [...document.images].slice(0, 300)) {
    const r = img.getBoundingClientRect();
    if (r.width && r.right > vw + 1 && !inScroller(img)) { add('image-overflow', 'Image is ' + Math.round(r.width) + 'px wide in a ' + vw + 'px viewport.', img); break; }
  }
  return {
    url: location.href,
    title: document.title,
    viewport: { width: vw, height: vh, dpr: devicePixelRatio, pageWidth: de.scrollWidth, pageHeight: de.scrollHeight, layoutScaled: vw !== innerWidth ? innerWidth : undefined },
    issues,
    scanned: all.length,
  };
})`;

const DEFAULT_OPTS = { maxElements: 2500, perKind: 5, tapMin: 44, minFont: 12, touch: true };

// What a media query can change: which elements are shown, how containers lay out, and how many columns they use.
// Pixel positions are deliberately excluded: on a fluid layout they shift at every width and every width then
// looks like a breakpoint.
const SIGNATURE = `(() => {
  const els = [...document.body.querySelectorAll('*')].slice(0, 600);
  let sig = '';
  for (const e of els) {
    const cs = getComputedStyle(e);
    if (cs.display === 'none') { sig += '0|'; continue; }
    const tracks = cs.display.includes('grid') ? cs.gridTemplateColumns.split(' ').length : 0;
    // how many rows a wrapping container has broken into: catches a nav or card grid rewrapping
    const wraps = (cs.flexWrap === 'wrap' || cs.display.includes('grid')) && e.children.length > 1
      ? new Set([...e.children].slice(0, 12).map(c => Math.round(c.getBoundingClientRect().top / 4))).size : 0;
    sig += cs.display[0] + (cs.flexDirection === 'column' ? 'c' : 'r') + cs.position[0] + tracks + ':' + wraps + '|';
  }
  let h = 0; for (let i = 0; i < sig.length; i++) h = (h * 33 + sig.charCodeAt(i)) | 0;
  return { hash: String(h) };
})`;

// Breakpoints as the stylesheets declare them: the authoritative answer when the CSS is readable.
const DECLARED = `(() => {
  const root = parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
  const out = new Set(); let readable = 0, blocked = 0;
  const walk = rules => {
    for (const r of rules) {
      if (r.media && r.media.mediaText) {
        for (const m of r.media.mediaText.matchAll(/\\((?:min|max)-width:\\s*([\\d.]+)(px|em|rem)\\)/g)) {
          const v = parseFloat(m[1]); out.add(Math.round(m[2] === 'px' ? v : v * root));
        }
      }
      if (r.cssRules) walk(r.cssRules);
    }
  };
  for (const sheet of document.styleSheets) {
    try { walk(sheet.cssRules); readable++; } catch { blocked++; }
  }
  return { widths: [...out].sort((a, b) => a - b), readable, blocked };
})`;

// ---------- src/cdp.mjs ----------
// A small Chrome DevTools Protocol client. No dependencies: Node's built-in WebSocket drives the Chrome that is
// already installed, so this file plus Node is the whole runtime.

const CANDIDATES = {
  linux: ['/usr/bin/google-chrome', '/usr/bin/google-chrome-stable', '/usr/bin/chromium', '/usr/bin/chromium-browser', '/snap/bin/chromium', '/opt/google/chrome/chrome'],
  darwin: ['/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', '/Applications/Chromium.app/Contents/MacOS/Chromium', '/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge'],
  win32: ['C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', 'C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe', 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe'],
};

function findChrome(explicit) {
  for (const p of [explicit, process.env.CHROME_PATH, ...(CANDIDATES[process.platform] || [])].filter(Boolean)) if (existsSync(p)) return p;
  for (const name of ['google-chrome', 'google-chrome-stable', 'chromium', 'chromium-browser', 'microsoft-edge']) {
    try { const p = execFileSync(process.platform === 'win32' ? 'where' : 'which', [name], { encoding: 'utf8' }).split('\n')[0].trim(); if (p && existsSync(p)) return p; } catch {}
  }
  throw new Error('Could not find Chrome. Install Google Chrome or Chromium, or set CHROME_PATH to the executable.');
}

class Connection {
  constructor(ws) {
    this.ws = ws; this.id = 0; this.pending = new Map(); this.listeners = new Set();
    ws.addEventListener('message', e => {
      let msg; try { msg = JSON.parse(e.data); } catch { return; }
      if (msg.id && this.pending.has(msg.id)) {
        const { resolve, reject, timer } = this.pending.get(msg.id); this.pending.delete(msg.id); clearTimeout(timer);
        msg.error ? reject(new Error(msg.error.message || JSON.stringify(msg.error))) : resolve(msg.result);
      } else if (msg.method) for (const fn of this.listeners) fn(msg);
    });
    ws.addEventListener('close', () => { for (const { reject, timer } of this.pending.values()) { clearTimeout(timer); reject(new Error('Chrome connection closed')); } this.pending.clear(); });
  }
  send(method, params = {}, sessionId, timeout = 45000) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { this.pending.delete(id); reject(new Error(`${method} timed out after ${timeout}ms`)); }, timeout);
      this.pending.set(id, { resolve, reject, timer });
      this.ws.send(JSON.stringify(sessionId ? { id, method, params, sessionId } : { id, method, params }));
    });
  }
  on(fn) { this.listeners.add(fn); return () => this.listeners.delete(fn); }
  close() { try { this.ws.close(); } catch {} }
}

// One browser per process, started on first use.
let browser = null, opts = {};
function configure(o) { opts = { ...opts, ...o }; }

async function wsFromEndpoint(endpoint) {
  const base = endpoint.startsWith('http') ? endpoint : `http://${endpoint}`;
  const r = await fetch(new URL('/json/version', base));
  if (!r.ok) throw new Error(`Chrome at ${base} did not answer /json/version (${r.status}).`);
  return (await r.json()).webSocketDebuggerUrl;
}

async function connect(url) {
  if (typeof WebSocket !== 'function') throw new Error('This Node build has no WebSocket. Node 22 or newer is required.');
  const ws = new WebSocket(url);
  await new Promise((res, rej) => {
    const t = setTimeout(() => rej(new Error('Timed out connecting to Chrome')), 20000);
    ws.addEventListener('open', () => { clearTimeout(t); res(); });
    ws.addEventListener('error', () => { clearTimeout(t); rej(new Error('Could not connect to Chrome')); });
  });
  return new Connection(ws);
}

async function getBrowser() {
  if (browser) return browser;
  if (opts.connect) { browser = { conn: await connect(await wsFromEndpoint(opts.connect)), attached: true }; return browser; }
  const bin = findChrome(opts.chromePath);
  const profile = opts.profile || mkdtempSync(join(tmpdir(), 'viewport-wall-'));
  const args = [
    opts.headed ? '--remote-debugging-port=0' : '--headless=new', '--remote-debugging-port=0',
    `--user-data-dir=${profile}`, '--no-first-run', '--no-default-browser-check', '--hide-scrollbars',
    '--disable-backgrounding-occluded-windows', '--disable-renderer-backgrounding', '--disable-features=Translate',
    ...(opts.args || []), 'about:blank',
  ].filter((a, i, all) => all.indexOf(a) === i);
  const proc = spawn(bin, args, { stdio: ['ignore', 'pipe', 'pipe'] });
  const url = await new Promise((res, rej) => {
    let buf = '';
    const timer = setTimeout(() => rej(new Error('Chrome did not report a debugging port in 30s')), 30000);
    proc.stderr.on('data', d => { buf += d; const m = buf.match(/ws:\/\/[^\s]+/); if (m) { clearTimeout(timer); res(m[0]); } });
    proc.on('exit', c => { clearTimeout(timer); rej(new Error(`Chrome exited (${c}) before it was ready. ${buf.split('\n').slice(-3).join(' ')}`)); });
  });
  browser = { conn: await connect(url), proc, profile, temp: !opts.profile };
  return browser;
}

async function closeBrowser() {
  const b = browser; browser = null;
  if (!b) return;
  try { if (!b.attached) await b.conn.send('Browser.close').catch(() => {}); } catch {}
  b.conn.close();
  if (b.proc) { try { b.proc.kill(); } catch {} }
}
for (const sig of ['SIGINT', 'SIGTERM']) process.on(sig, () => closeBrowser().finally(() => process.exit(0)));

// One tab, with the CDP calls the audit needs.
class Page {
  static async open() {
    const { conn } = await getBrowser();
    const { targetId } = await conn.send('Target.createTarget', { url: 'about:blank' });
    const { sessionId } = await conn.send('Target.attachToTarget', { targetId, flatten: true });
    const page = new Page(conn, targetId, sessionId);
    await page.send('Page.enable');
    await page.send('Runtime.enable');
    await page.send('Network.enable');
    page.offEvent = conn.on(msg => { if (msg.sessionId === sessionId) page.handle(msg); });
    return page;
  }
  constructor(conn, targetId, sessionId) {
    this.conn = conn; this.targetId = targetId; this.sessionId = sessionId;
    this.inflight = 0; this.waiters = new Set();
  }
  send(method, params, timeout) { return this.conn.send(method, params, this.sessionId, timeout); }
  handle(msg) {
    if (msg.method === 'Network.requestWillBeSent') this.inflight++;
    else if (msg.method === 'Network.loadingFinished' || msg.method === 'Network.loadingFailed') this.inflight = Math.max(0, this.inflight - 1);
    for (const w of this.waiters) w(msg);
  }
  once(method, timeout = 30000) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { this.waiters.delete(w); reject(new Error(`Timed out waiting for ${method}`)); }, timeout);
      const w = msg => { if (msg.method === method) { clearTimeout(timer); this.waiters.delete(w); resolve(msg.params); } };
      this.waiters.add(w);
    });
  }
  async setViewport({ width, height, dpr = 1, mobile = false, touch = false }) {
    await this.send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: dpr, mobile: !!mobile, screenWidth: width, screenHeight: height });
    await this.send('Emulation.setTouchEmulationEnabled', { enabled: !!touch, maxTouchPoints: touch ? 5 : 0 }).catch(() => {});
  }
  setUserAgent(ua) { return this.send('Network.setUserAgentOverride', { userAgent: ua }); }
  async goto(url, { waitUntil = 'networkidle2', timeout = 30000, settle = 400 } = {}) {
    const load = waitUntil === 'domcontentloaded' ? this.once('Page.domContentEventFired', timeout) : this.once('Page.loadEventFired', timeout);
    const res = await this.send('Page.navigate', { url }, timeout);
    if (res.errorText) throw new Error(`${res.errorText} for ${url}`);
    await load.catch(() => {});                       // a page that never fires load is still worth checking
    if (waitUntil.startsWith('networkidle')) await this.waitIdle(waitUntil === 'networkidle0' ? 0 : 2, timeout);
    if (settle) await new Promise(r => setTimeout(r, settle));
    return res;
  }
  async waitIdle(max = 2, timeout = 15000) {
    const start = Date.now();
    let quietSince = null;
    while (Date.now() - start < timeout) {
      if (this.inflight <= max) { quietSince ??= Date.now(); if (Date.now() - quietSince > 500) return; }
      else quietSince = null;
      await new Promise(r => setTimeout(r, 60));
    }
  }
  async evaluate(expression) {
    const r = await this.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error('Page script failed: ' + (r.exceptionDetails.exception?.description || r.exceptionDetails.text));
    return r.result.value;
  }
  async screenshot({ format = 'jpeg', quality = 75, fullPage = false } = {}) {
    const params = { format, ...(format === 'jpeg' ? { quality } : {}), optimizeForSpeed: true };
    if (fullPage) {
      const m = await this.send('Page.getLayoutMetrics');
      const w = Math.ceil(m.cssContentSize.width), h = Math.min(Math.ceil(m.cssContentSize.height), 16000);
      Object.assign(params, { captureBeyondViewport: true, clip: { x: 0, y: 0, width: w, height: h, scale: 1 } });
    }
    return (await this.send('Page.captureScreenshot', params, 60000)).data;
  }
  async close() {
    this.offEvent?.();
    await this.conn.send('Target.closeTarget', { targetId: this.targetId }).catch(() => {});
  }
}

// ---------- src/audit.mjs ----------
// The actual work: emulate a device, load a page, run the checks, take pictures.

const allDevices = () => DEVICES;
const findDevice = id => DEVICES.find(d => d.id === id) || DEVICES.find(d => d.name.toLowerCase() === String(id).toLowerCase());
const findSet = id => SETS.find(s => s.id === id || s.name.toLowerCase() === String(id).toLowerCase());

function widthDevice(w, h = w < 700 ? 800 : 900) {
  return { id: `w-${w}`, name: `${w}px`, brand: 'Width', category: 'breakpoint', os: 'any', width: w, height: h, dpr: w < 700 ? 2 : 1, mobile: w < 1024, touch: w < 1024 };
}

// Accepts device ids, set ids, or plain numbers ("390") and returns device profiles.
function resolveDevices(list) {
  const out = [];
  for (const raw of list) {
    const item = String(raw).trim();
    if (/^\d+$/.test(item)) { out.push(widthDevice(+item)); continue; }
    const set = findSet(item);
    if (set) { for (const id of set.deviceIds) { const d = findDevice(id); if (d) out.push(d); } continue; }
    const d = findDevice(item);
    if (d) out.push(d); else throw new Error(`Unknown device or set: "${item}". Call list_devices to see valid ids.`);
  }
  const seen = new Set();
  return out.filter(d => !seen.has(d.id) && seen.add(d.id));
}

const uaFor = d => d.mobile ? (UA[d.os] || UA.mobile) : undefined;

async function withPage(device, fn, { mobileUA = false } = {}) {
  const page = await Page.open();
  try {
    await page.setViewport({ width: device.width, height: device.height, dpr: device.dpr || 1, mobile: !!device.mobile, touch: !!device.touch });
    if (mobileUA && uaFor(device)) await page.setUserAgent(uaFor(device));
    return await fn(page);
  } finally { await page.close().catch(() => {}); }
}

async function load(page, url, opts = {}) {
  await page.goto(url, opts).catch(e => { throw new Error(`Could not load ${url}: ${e.message}`); });
  return { status: null };
}

async function auditDevice(url, device, opts = {}) {
  const checkOpts = { ...DEFAULT_OPTS, ...opts.checks, touch: opts.checks?.touch ?? !!device.mobile };
  return withPage(device, async page => {
    const { status } = await load(page, url, opts);
    const result = await page.evaluate(`${CHECKS}(${JSON.stringify(checkOpts)})`);
    const out = { device: { id: device.id, name: device.name, width: device.width, height: device.height, dpr: device.dpr || 1, mobile: !!device.mobile }, status, ...result };
    if (opts.screenshot) out.screenshot = await page.screenshot({ format: 'jpeg', quality: 70, fullPage: !!opts.fullPage });
    return out;
  }, opts);
}

async function audit(url, devices, opts = {}) {
  const results = [];
  const limit = Math.max(1, Math.min(opts.concurrency || 3, 6));
  const queue = [...devices];
  await Promise.all(Array.from({ length: Math.min(limit, queue.length) }, async () => {
    while (queue.length) {
      const d = queue.shift();
      try { results.push(await auditDevice(url, d, opts)); }
      catch (e) { results.push({ device: { id: d.id, name: d.name, width: d.width, height: d.height }, error: String(e.message || e), issues: [] }); }
    }
  }));
  results.sort((a, b) => devices.findIndex(d => d.id === a.device.id) - devices.findIndex(d => d.id === b.device.id));
  return results;
}

async function shoot(url, device, opts = {}) {
  return withPage(device, async page => {
    await load(page, url, opts);
    const data = await page.screenshot({ format: opts.format === 'png' ? 'png' : 'jpeg', quality: opts.quality || 75, fullPage: !!opts.fullPage });
    return { device, data, mimeType: opts.format === 'png' ? 'image/png' : 'image/jpeg' };
  }, opts);
}

// Two answers: what the stylesheets declare, and what the layout actually does when swept.
async function breakpoints(url, { min = 320, max = 1600, step = 16, ...opts } = {}) {
  const page = await Page.open();
  try {
    await page.setViewport({ width: max, height: 900 });
    await load(page, url, opts);
    const declared = await page.evaluate(`${DECLARED}()`);
    const inRange = declared.widths.filter(w => w >= min && w <= max);

    const sigAt = async w => {
      await page.setViewport({ width: w, height: w < 700 ? 800 : 900, mobile: w < 1024, touch: w < 1024 });
      await new Promise(r => setTimeout(r, 110));
      return (await page.evaluate(`${SIGNATURE}()`)).hash;
    };
    const changes = [];
    let prev = await sigAt(min), prevW = min;
    for (let w = min + step; w <= max; w += step) {
      const sig = await sigAt(w);
      if (sig !== prev) changes.push([prevW, w]);
      prev = sig; prevW = w;
    }
    const exact = [];
    for (const [lo0, hi0] of changes.slice(0, 40)) {      // bisect each change to the exact pixel
      let lo = lo0, hi = hi0;
      const loSig = await sigAt(lo);
      while (hi - lo > 1) {
        const mid = Math.floor((lo + hi) / 2);
        if (await sigAt(mid) === loSig) lo = mid; else hi = mid;
      }
      exact.push(hi);
    }
    return { url, range: [min, max], declared: inRange, observed: [...new Set(exact)].sort((a, b) => a - b), stylesheets: { readable: declared.readable, blocked: declared.blocked } };
  } finally { await page.close().catch(() => {}); }
}

const commonWidths = QUICK_WIDTHS;

// ---------- src/rpc.mjs ----------
// Minimal MCP server over stdio: newline-delimited JSON-RPC 2.0, the three methods a client needs, and ping.
// Hand-rolled so the package has no dependencies and can ship as one file.
const PROTOCOL = '2024-11-05';

function serve({ name, version, tools, call }) {
  const send = msg => process.stdout.write(JSON.stringify(msg) + '\n');
  const reply = (id, result) => send({ jsonrpc: '2.0', id, result });
  const fail = (id, code, message) => send({ jsonrpc: '2.0', id, error: { code, message } });

  const handle = async msg => {
    const { id, method, params } = msg;
    if (id === undefined) return;                      // a notification: nothing to answer
    try {
      if (method === 'initialize') {
        return reply(id, {
          protocolVersion: params?.protocolVersion === '2025-06-18' ? params.protocolVersion : PROTOCOL,
          capabilities: { tools: { listChanged: false } },
          serverInfo: { name, version },
        });
      }
      if (method === 'ping') return reply(id, {});
      if (method === 'tools/list') return reply(id, { tools });
      if (method === 'tools/call') {
        const tool = tools.find(t => t.name === params?.name);
        if (!tool) return reply(id, { isError: true, content: [{ type: 'text', text: `Unknown tool: ${params?.name}` }] });
        try { return reply(id, await call(params.name, params.arguments || {})); }
        catch (e) { return reply(id, { isError: true, content: [{ type: 'text', text: String(e?.message || e) }] }); }
      }
      if (method === 'resources/list') return reply(id, { resources: [] });
      if (method === 'prompts/list') return reply(id, { prompts: [] });
      fail(id, -32601, `Method not found: ${method}`);
    } catch (e) { fail(id, -32603, String(e?.message || e)); }
  };

  let buf = '';
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', chunk => {
    buf += chunk;
    let i;
    while ((i = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, i).trim(); buf = buf.slice(i + 1);
      if (!line) continue;
      let msg; try { msg = JSON.parse(line); } catch { continue; }
      Array.isArray(msg) ? msg.forEach(handle) : handle(msg);
    }
  });
  process.stdin.on('end', () => process.exit(0));
}

// ---------- src/index.mjs ----------
// viewport-wall-mcp: an MCP server (default) and a CLI over the same engine.
//   MCP:  viewport-wall-mcp
//   CLI:  viewport-wall-mcp audit https://example.com --devices popular-mobile,1440

const VERSION = '1.0.0';
const DEFAULT_DEVICES = ['iphone-se', 'iphone-17-pro', 'pixel-10', 'ipad-pro-11', 'laptop-1366', 'desktop-1920'];

// ---------- shared formatting ----------
const fmtIssue = i => `  - [${i.kind}] ${i.message}${i.element ? `\n    element: ${i.element}` : ''}`;
function fmtAudit(url, results) {
  const total = results.reduce((n, r) => n + (r.issues?.length || 0), 0);
  const broken = results.filter(r => r.issues?.length);
  const head = [
    `Responsive audit of ${url}`,
    `${results.length} viewport${results.length === 1 ? '' : 's'} checked, ${total} issue${total === 1 ? '' : 's'} found on ${broken.length} of them.`,
    total === 0 ? 'No layout problems detected by these rules. Rules catch structural breakage, not visual taste: ask for screenshots to judge the design.' : '',
  ].filter(Boolean);
  const body = results.map(r => {
    const d = r.device;
    const title = `${d.name} — ${d.width}x${d.height} @${d.dpr || 1}x${d.mobile ? ' (touch)' : ''}`;
    if (r.error) return `${title}\n  ! ${r.error}`;
    if (!r.issues.length) return `${title}\n  ok`;
    return `${title}  [page is ${r.viewport.pageWidth}px wide]\n` + r.issues.map(fmtIssue).join('\n');
  });
  return head.join('\n') + '\n\n' + body.join('\n\n');
}

function fmtBreakpoints(r) {
  const lines = [`Breakpoints for ${r.url} between ${r.range[0]}px and ${r.range[1]}px`];
  lines.push(r.declared.length ? `Declared in CSS: ${r.declared.join('px, ')}px` : 'Declared in CSS: none found in this range');
  if (r.stylesheets.blocked) lines.push(`(${r.stylesheets.blocked} stylesheet${r.stylesheets.blocked === 1 ? '' : 's'} could not be read across origins, so declared widths may be incomplete.)`);
  lines.push(r.observed.length ? `Layout observed to change at: ${r.observed.join('px, ')}px` : 'Layout observed to change at: nowhere, the page reflows fluidly');
  const test = [...new Set([...r.declared, ...r.observed])].sort((a, b) => a - b);
  if (test.length) lines.push('', `Worth auditing just below and at each: ${test.map(w => `${w - 1}, ${w}`).join(', ')}`);
  return lines.join('\n');
}

// ---------- MCP ----------
const TOOLS = [
  {
    name: 'audit_responsive',
    description: 'Check a web page for responsive layout problems across several device viewports at once. Returns, per device, the viewport it used and every issue found: horizontal overflow, elements running past the viewport edge, clipped text, fixed or sticky elements overflowing, images wider than the screen, tap targets under 44px, text under 12px, and a missing viewport meta tag. Each issue names the element that caused it. Start here; ask for screenshots only for the devices that failed.',
    inputSchema: {
      type: 'object',
      properties: {
        url: { type: 'string', description: 'Page to check. http(s) or a localhost address.' },
        devices: { type: 'array', items: { type: 'string' }, description: `Device ids, set ids, or plain pixel widths like "390". Defaults to ${DEFAULT_DEVICES.join(', ')}. Call list_devices for the full library.` },
        include_screenshots: { type: 'boolean', description: 'Also return a picture of each viewport. Expensive in tokens: prefer a targeted screenshot call. Default false.' },
        full_page: { type: 'boolean', description: 'Screenshots capture the whole scrollable page instead of the visible viewport. Default false.' },
        mobile_user_agent: { type: 'boolean', description: 'Send a phone user agent on mobile devices. Off by default because it logs some sites out.' },
        wait_until: { type: 'string', enum: ['load', 'domcontentloaded', 'networkidle0', 'networkidle2'], description: 'When the page counts as loaded. Default networkidle2.' },
        timeout_ms: { type: 'number', description: 'Per page load. Default 30000.' },
      },
      required: ['url'],
    },
  },
  {
    name: 'screenshot',
    description: 'Take a picture of a page at one or more device viewports and return the images, so you can judge the layout with your own eyes rather than by rules.',
    inputSchema: {
      type: 'object',
      properties: {
        url: { type: 'string' },
        devices: { type: 'array', items: { type: 'string' }, description: 'Device ids, set ids or pixel widths. Default iphone-17-pro.' },
        full_page: { type: 'boolean', description: 'Whole scrollable page instead of the visible viewport.' },
        format: { type: 'string', enum: ['jpeg', 'png'], description: 'Default jpeg.' },
      },
      required: ['url'],
    },
  },
  {
    name: 'find_breakpoints',
    description: 'Report the widths where a page responds: the breakpoints its stylesheets declare, and the widths where the layout is observed to change when the viewport is swept. Use it to pick which widths are worth auditing.',
    inputSchema: {
      type: 'object',
      properties: {
        url: { type: 'string' },
        min: { type: 'number', description: 'Default 320.' },
        max: { type: 'number', description: 'Default 1600.' },
        step: { type: 'number', description: 'Coarse sweep step in px, refined to the exact pixel afterwards. Default 8.' },
      },
      required: ['url'],
    },
  },
  {
    name: 'list_devices',
    description: 'List the device profiles available to the other tools: phones, foldables (open and closed), tablets, laptops, desktops, watches and TVs, plus named sets and common widths.',
    inputSchema: {
      type: 'object',
      properties: {
        category: { type: 'string', enum: ['phone', 'foldable', 'tablet', 'laptop', 'desktop', 'watch', 'tv'], description: 'Filter by category.' },
        query: { type: 'string', description: 'Match against name or brand, e.g. "pixel".' },
      },
    },
  },
];

async function runTool(name, a = {}) {
  if (name === 'list_devices') {
    let list = allDevices().filter(d => d.category !== 'breakpoint');
    if (a.category) list = list.filter(d => d.category === a.category);
    if (a.query) { const q = a.query.toLowerCase(); list = list.filter(d => (d.name + ' ' + d.brand).toLowerCase().includes(q)); }
    const byCat = {};
    for (const d of list) (byCat[d.category] ||= []).push(`${d.id} — ${d.name} ${d.width}x${d.height} @${d.dpr}x`);
    const text = Object.entries(byCat).map(([c, rows]) => `${c.toUpperCase()}\n` + rows.map(r => '  ' + r).join('\n')).join('\n\n')
      + `\n\nSETS (pass a set id in place of a device)\n` + SETS.map(s => `  ${s.id} — ${s.name} (${s.deviceIds.length})`).join('\n')
      + `\n\nAny plain number works too, e.g. "375". Common widths: ${commonWidths.join(', ')}.`;
    return { content: [{ type: 'text', text }] };
  }
  if (name === 'audit_responsive') {
    const devices = resolveDevices(a.devices?.length ? a.devices : DEFAULT_DEVICES);
    const results = await audit(a.url, devices, {
      screenshot: !!a.include_screenshots, fullPage: !!a.full_page, mobileUA: !!a.mobile_user_agent,
      waitUntil: a.wait_until || 'networkidle2', timeout: a.timeout_ms || 30000,
    });
    const content = [{ type: 'text', text: fmtAudit(a.url, results) }];
    for (const r of results) if (r.screenshot) content.push({ type: 'image', data: r.screenshot, mimeType: 'image/jpeg' });
    return { content };
  }
  if (name === 'screenshot') {
    const devices = resolveDevices(a.devices?.length ? a.devices : ['iphone-17-pro']);
    const content = [];
    for (const d of devices) {
      const s = await shoot(a.url, d, { fullPage: !!a.full_page, format: a.format || 'jpeg' });
      content.push({ type: 'text', text: `${d.name} — ${d.width}x${d.height} @${d.dpr}x` });
      content.push({ type: 'image', data: s.data, mimeType: s.mimeType });
    }
    return { content };
  }
  if (name === 'find_breakpoints') {
    const r = await breakpoints(a.url, { min: a.min ?? 320, max: a.max ?? 1600, step: a.step ?? 16 });
    return { content: [{ type: 'text', text: fmtBreakpoints(r) }] };
  }
  throw new Error(`Unknown tool: ${name}`);
}

function startServer() { serve({ name: 'viewport-wall', version: VERSION, tools: TOOLS, call: runTool }); }

// ---------- CLI ----------
const HELP = `viewport-wall-mcp ${VERSION}

  viewport-wall-mcp                        run as an MCP server over stdio (what agents use)
  viewport-wall-mcp audit <url>            check a page across devices
  viewport-wall-mcp shot <url>             save screenshots
  viewport-wall-mcp breakpoints <url>      find the widths where layout changes
  viewport-wall-mcp devices [query]        list device ids

Options
  --devices a,b,390     device ids, set ids or widths      --full-page
  --json                machine-readable output            --out DIR       where shots are written (default .)
  --headed              show the browser                   --chrome PATH   Chrome executable
  --profile DIR         Chrome profile, keeps you logged in
  --connect URL         attach to a Chrome already running with --remote-debugging-port
`;

function parseArgs(argv) {
  const out = { _: [], flags: {} };
  for (let i = 0; i < argv.length; i++) {
    const t = argv[i];
    if (t.startsWith('--')) {
      const k = t.slice(2);
      if (['json', 'full-page', 'headed'].includes(k)) out.flags[k] = true;
      else out.flags[k] = argv[++i];
    } else out._.push(t);
  }
  return out;
}

async function cli(argv) {
  const { _: pos, flags } = parseArgs(argv);
  const [cmd, url] = pos;
  if (!cmd || flags.help || cmd === 'help') { console.log(HELP); return 0; }
  configure({ headed: !!flags.headed, chromePath: flags.chrome, profile: flags.profile, connect: flags.connect });
  const devices = flags.devices ? flags.devices.split(',').map(s => s.trim()).filter(Boolean) : null;
  if (cmd === 'devices') {
    const r = await runTool('list_devices', { query: url });
    console.log(r.content[0].text); return 0;
  }
  if (!url) { console.error(`Missing URL.\n\n${HELP}`); return 2; }
  if (cmd === 'audit') {
    const list = resolveDevices(devices || DEFAULT_DEVICES);
    const results = await audit(url, list, { fullPage: !!flags['full-page'] });
    if (flags.json) console.log(JSON.stringify({ url, results }, null, 2));
    else console.log(fmtAudit(url, results));
    return results.some(r => r.issues?.length) ? 1 : 0;   // non-zero exit when something is broken, so CI can use it
  }
  if (cmd === 'shot') {
    const { writeFileSync, mkdirSync } = await import('node:fs');
    const dir = flags.out || '.'; mkdirSync(dir, { recursive: true });
    const list = resolveDevices(devices || ['iphone-17-pro']);
    const written = [];
    for (const d of list) {
      const s = await shoot(url, d, { fullPage: !!flags['full-page'], format: 'png' });
      const f = `${dir}/${d.id}-${d.width}x${d.height}.png`;
      writeFileSync(f, Buffer.from(s.data, 'base64')); written.push(f);
    }
    console.log(flags.json ? JSON.stringify(written, null, 2) : written.join('\n'));
    return 0;
  }
  if (cmd === 'breakpoints') {
    const r = await breakpoints(url, { min: +(flags.min || 320), max: +(flags.max || 1600), step: +(flags.step || 16) });
    console.log(flags.json ? JSON.stringify(r, null, 2) : fmtBreakpoints(r));
    return 0;
  }
  console.error(`Unknown command "${cmd}".\n\n${HELP}`); return 2;
}

const args = process.argv.slice(2);
if (args.length === 0) {
  configure({ chromePath: process.env.CHROME_PATH, profile: process.env.VIEWPORT_WALL_PROFILE, connect: process.env.VIEWPORT_WALL_CONNECT });
  startServer();
} else {
  cli(args).then(async code => { await closeBrowser(); process.exit(code); }, async e => { console.error(String(e.message || e)); await closeBrowser(); process.exit(1); });
}
